  2028  /*
  2029   * Fixes any PP links in @PG headers.
  2030   * If the entries are in order then this doesn't need doing, but incase
  2031   * our header is out of order this goes through the hrecs->pg[] array
  2032   * setting the prev_id field.
  2033   *
  2034   * Note we can have multiple complete chains. This code should identify the
  2035   * tails of these chains as these are the entries we have to link to in
  2036   * subsequent PP records.
  2037   *
  2038   * Returns 0 on success
  2039   *        -1 on failure (indicating broken PG/PP records)
  2040   */
  2041  static int sam_hdr_link_pg(sam_hdr_t *bh) {
  2042      sam_hrecs_t *hrecs;
  2043      int i, j, ret = 0, *new_pg_end;
  2044
  2045      if (!bh)
  2046          return -1;
  2047
  2048      if (!(hrecs = bh->hrecs)) {
  2049          if (sam_hdr_fill_hrecs(bh) != 0)
  2050              return -1;
  2051          hrecs = bh->hrecs;
  2052      }
  2053
  2054      if (!hrecs->pgs_changed || !hrecs->npg)
  2055          return 0;
  2056
  2057      hrecs->npg_end_alloc = hrecs->npg;
  2058      new_pg_end = realloc(hrecs->pg_end, hrecs->npg * sizeof(*new_pg_end));
  2059      if (!new_pg_end)
  2060          return -1;
  2061      hrecs->pg_end = new_pg_end;
  2062      int *chain_size = calloc(hrecs->npg, sizeof(int));
  2063      if (!chain_size)
  2064          return -1;
  2065
  2066      for (i = 0; i < hrecs->npg; i++)
  2067          hrecs->pg_end[i] = i;
  2068
  2069      for (i = 0; i < hrecs->npg; i++) {
  2070          khint_t k;
  2071          sam_hrec_tag_t *tag;
  2072
  2073          assert(hrecs->pg[i].ty != NULL);
  2074          for (tag = hrecs->pg[i].ty->tag; tag; tag = tag->next) {
  2075              if (tag->str[0] == 'P' && tag->str[1] == 'P')
  2076                  break;
  2077          }
  2078          if (!tag) {
  2079              /* Chain start points */
  2080              continue;
  2081          }
  2082
  2083          k = kh_get(m_s2i, hrecs->pg_hash, tag->str+3);
  2084
  2085          if (k == kh_end(hrecs->pg_hash)) {
  2086              hts_log_warning("PG line with PN:%s has a PP link to missing program '%s'",
  2087                      hrecs->pg[i].name, tag->str+3);
  2088              continue;
  2089          }
  2090
  2091          hrecs->pg[i].prev_id = hrecs->pg[kh_val(hrecs->pg_hash, k)].id;
  2092          hrecs->pg_end[kh_val(hrecs->pg_hash, k)] = -1;
  2093          chain_size[i] = chain_size[kh_val(hrecs->pg_hash, k)]+1;
  2094      }
  2095
  2096      for (i = j = 0; i < hrecs->npg; i++) {
  2097          if (hrecs->pg_end[i] != -1 && chain_size[i] > 0)
  2098              hrecs->pg_end[j++] = hrecs->pg_end[i];
  2099      }
